          "AF03:外:生": "タオルで腿を拭き、ベビードールを羽織る。リボンがうまく結べず、耳だけが赤い。結合の痕跡がまだ腿の内側に光っていた。\n\n「タオル……っ……手伝って……」\n\n「……汗……、おじさんの、せい……だからね……っ」\n\n※外出し後:\n\n「お腹……拭いて……っ……リボン……結んで……」",
          "AF03:中:生": "「タオル、取って。……ベビードール、着直すの手伝って。……リボン、後ろで結べる？」"
