          "MN07:prompt": "腰を押しつけたまま締めつけ、中に出される熱をねだる。止めないから全部と、もう拒めない顔だった。\n\n「中……出していい……っ……止めないから……全部……っ」\n\n脈打つ精液が子宮口へ叩きつけられ、腹の奥がじわりと膨らむ感触に背中が震えた。溢れそうな熱が結合部から伝わる。\n\n「あっ……あったかい……っ……いっぱい……んぅっ……」\n\n\n「あ……外……っ……んあっ……！　……お腹……熱い……っ……う、ぅっ……」",
          "MN07:中": "「あっ……あったかい……。……中、いっぱい……ん……」",
          "MN07:外": "「腰を浮かせた瞬間、ぬるりと空いた膣口から蜜が溢れた。腹の上に熱い精液が飛び、肌を伝って落ちる。」",
          "MN07:prompt:生": "腰を押しつけたまま締めつけ、中に出される熱をねだる。止めないから全部と、もう拒めない顔だった。\n\n「中……出していい……っ……止めないから……全部……っ」\n\n脈打つ精液が子宮口へ叩きつけられ、腹の奥がじわりと膨らむ感触に背中が震えた。溢れそうな熱が結合部から伝わる。\n\n「あっ……あったかい……っ……いっぱい……んぅっ……」\n\n\n「あ……外……っ……んあっ……！　……お腹……熱い……っ……う、ぅっ……」",
