          "FIN:prompt": "（息を荒げながら、目線だけ上げる）\n\n「……出す、前に言って。……どこ、がいい？」",
          "AF01:中:生": "降りようとして足がガクガクし、埋められたままの熱が膣内で脈打っている。まだ抜かれたくない。余韻で内壁が時折きゅっと締まった。\n\n「はぁ……はぁ……っ……降りる……足、ガクガク……っ……まだ、抜かないで……っ……抱き起こして……っ」\n\n\n「はぁ……はぁ……っ……離れないで……っ……まだ……余韻……っ……」",
          "AF01:外:生": "腹に張りついた精液が冷えはじめ、それでも腕の中から離れたくない。腿を擦り合わせ、空になった疼きを誤魔化す。",
