          "MN07:prompt": "後ろから腰を押しつけられ、奥を締めつけてねだる。後ろから中に出される熱を、もう拒めない顔だった。\n\n「中……出して……っ……後ろ、から……ちょうだい……っ」\n\n脈打つ精液が子宮口へ叩きつけられ、腹の奥がじわりと膨らむ感触に背中が震えた。溢れそうな熱が結合部から伝わる。\n\n「あっ……あったかい……っ……溢れる……んぅっ……」\n\n\n「あ……外……っ……んあっ……！　……お腹……熱い……っ……う、ぅっ……」",
