          "AF01:中": "男の体重が胸に乗り、埋められたままの熱が膣内で脈打っている。まだ抜かれたくない。余韻で内壁が時折きゅっと締まった。\n\n「はぁ……はぁ……っ……重い……。……まだ、抜かないで……っ……ちょっと、だけ……」\n\n\n「はぁ……はぁ……っ……離れないで……っ……まだ……余韻……っ……」",
