          "AF01:外:生": "腹に張りついた精液が冷えはじめ、それでも腕の中から離れたくない。腿を擦り合わせ、空になった疼きを誤魔化す。",
          "AF02:外:生": "胸に額を預け、指で特注制服の裾を掴んだ。指イキの羞恥が耳に残っている。\n\n「……ん……。……指……で……イかされて……っ……また……指名……して……ください……っ」\n\n※外出し後:\n\n「……外……だった、の……っ……次は……中……も……いい……ですか……？」",
          "AF02:中:生": "「……どう、でしたか？　私、可愛かった……？　……か、可愛くないです……っ」",
          "AF03:外:生": "タオルで腿を拭き、ベストを羽織る。ボタンがうまくはまらず、耳だけが赤い。\n\n「タオル……っ……手伝って……ください……」\n\n「……汗……、お客さんの、せい……です……っ……牛乳……ほしい……っ」\n\n※外出し後:\n\n「お腹……拭いて……ください……っ……制服……手伝って……」",
