          "AF01:中:生": "男の体重が胸に乗り、埋められたままの熱が膣内で脈打っている。まだ抜かれたくない。余韻で内壁が時折きゅっと締まった。\n\n「はぁ……はぁ……っ……重い……です……。……まだ、抜かないで……ください……っ……ちょっと、だけ……」\n\n\n「はぁ……はぁ……っ……離れないで……ください……っ……まだ……余韻……っ……」",
          "AF01:外:生": "腹に張りついた精液が冷えはじめ、それでも腕の中から離れたくない。腿を擦り合わせ、空になった疼きを誤魔化す。",
          "AF02:外:生": "うつ伏せから抱き起こされ、胸に額を預けた。後ろから出されたあとの熱が残っている。\n\n「……ん……。……後ろ……から……っ……また……指名……して……ください……っ」\n\n※外出し後:\n\n「……外……だった、の……っ……次は……中……も……いい……ですか……？」",
          "AF02:中:生": "「……どう、でしたか？　私、可愛かった……？　……か、可愛くないです……っ」",
          "AF03:外:生": "タオルで腿を拭き、ベストを羽織る。ボタンがうまくはまらず、耳だけが赤い。ポニーテールが乱れている。\n\n「タオル……っ……手伝って……ください……」\n\n「……汗……、お客さんの、せい……です……っ……牛乳……ほしい……っ」\n\n※外出し後:\n\n「背中……拭いて……ください……っ……制服……手伝って……」",
          "AF03:中:生": "「タオル、取ってください。……制服、着直すの、手伝って……。」"
