          "AF03:外": "タオルで腿を拭き、ベストを羽織る。ボタンがうまくはまらず、耳だけが赤い。\n\n「タオル……っ……手伝って……ください……」\n\n「……汗……、お客さんの、せい……です……っ……牛乳……ほしい……っ」\n\n※外出し後:\n\n「お腹……拭いて……ください……っ……制服……手伝って……」",
          "AF99": "ドアの前で振り返り、ポニーテールを揺らした。足はまだ少し揺れている。\n\n「……お疲れ……さまでした……っ。……二回戦……また……っ」",
          "MN04": "引き抜かれ、騎乗や後背へ変えられる。角度が変わると子宮口に深く当たり、谷間が揺れた。\n\n「……換わる……っ……二回目……っ……んあっ……深い……っ」\n\n「ん……っ……この角度……っ……だめ……っ」",
          "AF01": "埋められたままの熱が膣内で脈打っている。二回分の余韻で内壁が時折きゅっと締まった。\n\n「はぁ……はぁ……っ……重い……です……。……まだ、抜かないで……ください……っ……ちょっと、だけ……」\n\n※外出し後:\n\n「はぁ……はぁ……っ……離れないで……ください……っ……まだ……余韻……っ……」",
