            "奥を締めつけ、腰を押しつけてねだる。脈打つ精液が子宮口へ叩きつけられ、腹の奥がじわりと膨らむ。一回目の上に重ねられる熱。\n\n「出して……っ……二回目、も中……っ……全部……っ」\n\n「あっ……んぅ……っ……また……あったかい……っ……いっぱい……っ……ごちそう……さま……っ」\n\n\n「外……っ……んあっ……！　……二回目、も……お腹……っ……盛り付け……っ」"
