            "一回目の精液がまだ内壁に残り、ぬるぬるした膣口へ再び亀頭が沈んだ。敏感さが増し、華奢な脚が跳ねる。\n\n「っ……また……入っ……た……っ……二回目、敏感……んっ……！」",
            "再び亀頭が沈み、敏感な内壁が締めつける。\n\n「っ……三回目……っ……入っ……た……っ……んあっ……！」",
