          "MN07:prompt:生": "奥を抱き寄せるように締めつけ、腰を押しつけてねだる。生のまま中に出される熱を、もう拒めない顔だった。\n\n「中……出して……っ……全部……っ……上……のまま……っ」\n\n脈打つ精液が子宮口へ叩きつけられ、腹の奥がじわりと膨らむ感触に背中が震えた。\n\n「あっ……あったかい……っ……中、いっぱい……んぅっ……」\n\n\n「あ……外……っ……んあっ……！　……お腹……熱い……っ……う、ぅっ……」",
