          "AF01:中:生": "胸に崩れ落ち、埋められたままの熱が膣内で脈打っている。まだ抜かれたくない。余韻で内壁が時折きゅっと締まった。\n\n「はぁ……はぁ……っ……重い……。……まだ、抜かないで……っ……ちょっと、だけ……」\n\n\n「はぁ……はぁ……っ……離れないで……っ……まだ……余韻……っ……」",
