          "MN01": "亀頭が膣口を割り、一気に奥へ沈んだ。内壁が生の熱を締めつけ、脚が腰に絡みつく。根元まで埋まり、子宮口に当たる硬さで背中が反る。\n\n「っ……あ……っ……入っ……た……っ」\n\n「いっ……んっ……動かして……っ」\n\n「っ……あ……っ……生……入っ……た……っ……熱い……っ」",
