          "MN03": "腰の速度が上がり、肉が打ち合う音が部屋に響いた。丁寧に抑えていた息が崩れ、シーツは皺だらけになる。自分から腰を追ってしまう。\n\n「あっ……あっ、だめ……っ、そこ——んあっ！」\n\n「もっ、と……っ……奥……っ……足りな……い……っ」",
          "MN05": "内壁が勝手に痙攣しはじめ、腰が逃げようとしても逃げられない。クリトリスが結合の摩擦で擦れ、また絶頂がせり上がってくる。清楚な微笑みは消え、声が裏返った。\n\n「あ、っ……また……来る……っ……やだ、止まん……ない……っ」\n\n「んあっ、あっ、あっ……もっと……っ、ほしい……っ！」",
          "MN06": "子宮が締まり、膣が一気に男根を飲み込んだ。脚が痙攣し、つま先が丸まる。数秒、言葉にならず、涎が口の端から落ちた。\n\n「やだっ……あ、あ——っっ！」\n\n「ッ……は、ぁ……っ……まだ……足り……ない……っ」",
          "AF01:外": "腹に張りついた精液が冷えはじめ、それでも腕の中から離れたくない。腿を擦り合わせ、空になった疼きを誤魔化す。",
          "AF01:中": "男の体重が胸に乗り、埋められたままの熱が膣内で脈打っている。まだ抜かれたくない。余韻で内壁が時折きゅっと締まった。\n\n「はぁ……はぁ……っ……重い……。……まだ、抜かないで……っ……ちょっと、だけ……」\n\n\n「はぁ……はぁ……っ……離れないで……っ……まだ……余韻……っ……」",
          "AF02:外": "腹を拭いながらも、空の疼きが残っている。次は中に欲しがる目をした。",
          "AF02": "胸に額を預け、指先で相手のシャツを丸めた。汗と精液の匂いが鼻を満たす。事後のキスをねだり、舌先を這わせる。取り繕う微笑みが、すぐ崩れた。\n\n「……ねぇ……。……キス、もう一回……っ……ちゅ……ん……」\n\n「……大学……普通の子……に、見えてる……？　……私……こんな……っ」\n\n「……マッチング……で……会って……っ……こんなに……中……欲しがって……っ……変……？……っ」\n\n舌が混ざるたび、内壁が埋められた熱をきゅっと締め直す。耳まで赤いのに、腰だけが離れない。\n\n「……混ざる。……嫌じゃない……でしょ……。……ん……っ……もっと……話して……っ……このまま……っ」\n\n\n「……外……だった、の……っ……次は……中……も……いい……？　……話……しながら……っ」",
          "AF03:外": "「お腹……拭いて……っ……ブラウス……手伝って……」",
          "AF99": "ドアの前で振り返り、柔らかい微笑みを被り直した。足はまだ少し揺れている。事後の会話の余韻が、喉に残っていた。\n\n「……また……ホテル……、行きましょう……っ……次は……もっと……話……も……っ」",
          "AF10:中": "腕の中で息を整え、黒髪を直して柔らかい微笑みを被り直す。足はまだ小刻みに震えていた。膣内の熱が残るまま、言葉だけを取り繕う。\n\n「……気持ちよかった……。……本当……。……今、足、まだ震えてる……っ」\n\n「……清楚……って、言われる……っ……でも……中……は……こんな……っ」\n\n「……また、会える……？　……会えなくても……っ……私……また……欲しく……なる……っ」\n\n声を落とし、指で相手の胸を掴んだ。性欲の強さを認めた瞬間、耳がさらに赤くなる。\n\n「……本当は……もっと欲しい……っ……二回……も……三回……も……っ……言っちゃ……だめ……なのに……っ」\n\n微笑みに戻り、掠れた声で締めくくる。下着の内側は、まだべっとりと貼りついていた。\n\n「……今の……聞こえなかったことにして……っ……でも……また……ホテル……っ」",
          "AF03": "タオルで腿を拭き、ブラウスを羽織る。ボタンがうまくはまらず、耳だけが赤い。結合の痕跡がまだ腿の内側に光っていた。\n\n「タオル……っ……手伝って……」\n\n「……汗……、あなたの、せい……ですよ……っ」",
          "FIN:act:口": "（口の中で射精する）",
          "FIN:act:顔": "（顔にかけて射精する）",
          "FIN:act:胸": "（胸にかけて射精する）",
          "FIN:口": "「んっ……！ ……ごくん。……しょっぱ……。……上手、だった……？」",
          "FIN:顔": "「んあっ……！ ……顔……あったかい……っ……汚した……っ」",
          "FIN:胸": "「んっ……！ ……胸……あったかい……っ……受け止めた……っ」",
          "FIN:我慢": "「……ん、んっ……。……まだ……続ける……っ」",
          "FIN": "（フィニッシュのタイミング）\n\n「……出す……？　……どこ……っ」",
          "MN07:prompt": "奥を抱き寄せるように締めつけ、腰を押しつけてねだる。生のまま中に出される熱を、もう拒めない顔だった。\n\n「中……出して……っ……全部……っ」\n\n脈打つ精液が子宮口へ叩きつけられ、腹の奥がじわりと膨らむ感触に背中が震えた。\n\n「あっ……あったかい……っ……中、いっぱい……んぅっ……」\n\n\n「あ……外……っ……んあっ……！　……お腹……熱い……っ……う、ぅっ……」",
          "MN07:中": "「あっ……あったかい……。……中、いっぱい……ん……」",
          "MN07:外": "「引き抜かれた瞬間、ぬるりと空いた膣口から蜜が溢れた。腹の上に熱い精液が飛び、肌を伝って落ちる。」",
          "MN07:prompt:生": "奥を抱き寄せるように締めつけ、腰を押しつけてねだる。生のまま中に出される熱を、もう拒めない顔だった。\n\n「中……出して……っ……全部……っ」\n\n脈打つ精液が子宮口へ叩きつけられ、腹の奥がじわりと膨らむ感触に背中が震えた。\n\n「あっ……あったかい……っ……中、いっぱい……んぅっ……」\n\n\n「あ……外……っ……んあっ……！　……お腹……熱い……っ……う、ぅっ……」",
          "MN07:中:生": "「あっ……あったかい……。……中、いっぱい……ん……」",
          "MN07:外:生": "「引き抜かれた瞬間、ぬるりと空いた膣口から蜜が溢れた。腹の上に熱い精液が飛び、肌を伝って落ちる。」",
          "MN07:act:中:生": "（そのまま深く抱き寄せ、生のまま膣内で射精する）",
