          "AF02": "胸に額を預け、指で相手のシャツを掴んだ。何回分もの汗と精液の匂いが鼻を満たす。取り繕うように微笑もうとして、声だけが掠れた。\n\n「何回、出した？ ……数えてない。……私、覚えてる……っ」",
          "AF03:外": "「お腹……拭いて……っ……ブラウス……手伝って……」",
          "AF99": "ドアの前で振り返り、柔らかい微笑みを被り直した。足はまだ大きく揺れている。下着の内側は、出したばかりの熱でべっとりと貼りついていた。\n\n「……また……ホテル……、行きましょう……っ……次も……多回戦……っ」",
          "AF03": "タオルで腿を拭き、ブラウスを羽織る。ボタンがうまくはまらず、耳だけが赤い。結合の痕跡がまだ腿の内側に光っていた。\n\n「タオル……。……髪……結んで……」\n\n「……汗……、あなたの、せい……ですよ……っ」",
          "FIN:act:口": "（口の中で射精する）",
