            "奥を抱き寄せるように締めつけ、腰を押しつけてねだる。\n\n「出して……っ……二回目、も中……っ」\n\n脈打つ精液が子宮口へ叩きつけられ、腹の奥がじわりと膨らむ感触に背中が震えた。",
            "奥を抱き寄せるように締めつけ、腰を押しつけてねだる。\n\n「全部、出して……っ……三回目……ちょうだい……っ」\n\n脈打つ精液が子宮口へ叩きつけられ、腹の奥がじわりと膨らむ感触に背中が震えた。溢れそうな熱が結合部から伝わる。",
