          "FIN:prompt": "（息を整えながら、目線だけ上げる）\n\n「……出す、とき、……どこ、が、いい、ですか……？」",
          "AF01:中:生": "抱き合ったまま、心臓の音に耳を当てる。埋められた熱が膣内で脈打っている。まだ抜かれたくない。余韻で内壁が時折きゅっと締まった。\n\n「……まだ、抱き合って……。……抜くの、待って……っ……まだ、抜かないで……っ……」\n\n\n「はぁ……っ……離れないで……っ……まだ……余韻……っ……」",
          "AF01:外:生": "腹に張りついた精液が冷えはじめ、それでも腕の中から離れたくない。",
