          "MN07:外:生": "「引き抜かれた瞬間、ぬるりと空いた膣口から蜜が溢れた。腹の上に熱い精液が飛び、肌を伝って落ちる。」",
          "MN07:act:中:生": "（そのまま深く抱き寄せ、生のまま膣内で射精する）",
