          "FIN:prompt": "（息を整えながら、目線だけ上げる）\n\n「……出す、とき、……どこ、が、いい、ですか……？」",
          "AF01:中:生": "男の体重が胸に乗り、埋められたままの熱が膣内で脈打っている。まだ抜かれたくない。余韻で内壁が時折きゅっと締まった。谷間に残る熱が、まだ疼く。\n\n「はぁ……はぁ……っ……重い……。……まだ、抜かないで……っ……ちょっと、だけ……」",
          "AF01:外:生": "「はぁ……はぁ……っ……離れないで……っ……まだ……余韻……っ……」",
