          "MN07:prompt": "奥を抱き寄せるように締めつけ、腰を押しつけてねだる。生のまま中に出される熱を、もう拒めない顔だった。\n\n「中……出して……っ……全部……っ」\n\n脈打つ精液が子宮口へ叩きつけられ、腹の奥がじわりと膨らむ感触に背中が震えた。溢れそうな熱が結合部から伝わる。\n\n「あっ……あったかい……っ……中、いっぱい……んぅっ……」\n\n\n「あ……外……っ……んあっ……！　……お腹……熱い……っ……う、ぅっ……」",
          "MN07:中": "「あっ……あったかい……。……中、いっぱい……ん……」",
          "MN07:外": "「引き抜かれた瞬間、ぬるりと空いた膣口から蜜が溢れた。腹の上に熱い精液が飛び、肌を伝って落ちる。」",
          "MN07:prompt:生": "奥を抱き寄せるように締めつけ、腰を押しつけてねだる。生のまま中に出される熱を、もう拒めない顔だった。\n\n「中……出して……っ……全部……っ」\n\n脈打つ精液が子宮口へ叩きつけられ、腹の奥がじわりと膨らむ感触に背中が震えた。溢れそうな熱が結合部から伝わる。\n\n「あっ……あったかい……っ……中、いっぱい……んぅっ……」\n\n\n「あ……外……っ……んあっ……！　……お腹……熱い……っ……う、ぅっ……」",
          "MN07:中:生": "「あっ……あったかい……。……中、いっぱい……ん……」",
          "MN07:外:生": "「引き抜かれた瞬間、ぬるりと空いた膣口から蜜が溢れた。腹の上に熱い精液が飛び、肌を伝って落ちる。」",
          "MN07:act:中:生": "（そのまま深く抱き寄せ、生のまま膣内で射精する）",
