          "AF01:中:生": "仰向けのまま、口の端から白いものが垂れている。下も溢れ、腿の内側を伝ってシーツに染みる。動けない。余韻で内壁が時折きゅっと締まった。\n\n「はぁ……はぁ……っ……二人……に……出された……っ……」\n\n「動け……ない……っ……体……ぜんぶ……使った……っ……」",
          "AF01:外:生": "腹に張りついた精液が冷えはじめ、それでも腕の中から離れたくない。腿を擦り合わせ、空になった疼きを誤魔化す。",
          "AF02:外:生": "腹を拭いながらも、空の疼きが残っている。次は中に欲しがる目をした。",
