          "AF03:外:生": "シーツが汚れている。拭こうとして、腕が上がらない。二人にタオルを渡され、腿と口元を拭われる。ブラウスのボタンがうまくはまらず、耳だけが赤い。\n\n「タオル……っ……二人……で……拭いて……っ」\n\n「服……着られない……っ……手伝って……っ……」",
